import { describe, it, expect } from 'vitest'
import { enforceCadence } from '../shared/cadencePolicy'

describe('cadence policy', () => {
  it('FREE + daily => ineligible(cadence_mismatch)', () => {
    const res = enforceCadence('FREE', 'daily')
    expect(res.status).toBe('ineligible')
    if (res.status === 'ineligible') {
      expect(res.reason).toBe('cadence_mismatch')
    }
  })

  it('FREE + weekly => eligible', () => {
    const res = enforceCadence('FREE', 'weekly')
    expect(res.status).toBe('eligible')
  })

  it('PREMIUM + weekly => ineligible(cadence_mismatch)', () => {
    const res = enforceCadence('PREMIUM', 'weekly')
    expect(res.status).toBe('ineligible')
    if (res.status === 'ineligible') {
      expect(res.reason).toBe('cadence_mismatch')
    }
  })

  it('PREMIUM + daily => eligible', () => {
    const res = enforceCadence('PREMIUM', 'daily')
    expect(res.status).toBe('eligible')
  })

  it('invalid plan => ineligible(invalid_plan)', () => {
    const res = enforceCadence('ENTERPRISE', 'daily')
    expect(res.status).toBe('ineligible')
    if (res.status === 'ineligible') {
      expect(res.reason).toBe('invalid_plan')
    }
  })
})

import { describe, expect, it } from "vitest";
import { generateSummaryForWindow } from "../shared/summaryGeneration";
import type { SummaryUpdateRecord } from "../shared/summaryAggregation";

describe("summary generation entrypoint helper", () => {
  const baseArgs = {
    userId: "user_1",
    planInput: "FREE",
    requestedCadence: "weekly" as const,
    windowStart: 100,
    windowEnd: 200,
    selectedSchoolIds: ["school_a", "school_b"],
    generatedAt: 123456,
  };

  it("returns eligible output with scheduler metadata and payload", () => {
    const updates: SummaryUpdateRecord[] = [
      { schoolId: "school_a", updateId: "event_1", at: 150 },
      { schoolId: "school_a", updateId: "event_1", at: 150 }, // duplicate
      { schoolId: "school_b", updateId: "event_2", at: 199 },
      { schoolId: "school_x", updateId: "event_9", at: 160 }, // unselected
    ];

    const result = generateSummaryForWindow({ ...baseArgs, updates });

    expect(result.status).toBe("eligible");
    if (result.status !== "eligible") return;
    expect(result.plan).toBe("FREE");
    expect(result.cadence).toBe("weekly");
    expect(result.windowStart).toBe(100);
    expect(result.windowEnd).toBe(200);
    expect(result.generatedAt).toBe(123456);
    expect(result.selectedSchoolCount).toBe(2);
    expect(result.updatedSchoolCount).toBe(2);
    expect(result.missedSchoolsCount).toBe(0);
    expect(result.totalRelevantUpdates).toBe(2);
    expect(result.summaryPayload.missedSchoolsMessage).toBeNull();
  });

  it("returns ineligible for cadence mismatch with typed reason", () => {
    const result = generateSummaryForWindow({
      ...baseArgs,
      requestedCadence: "daily",
      updates: [],
    });

    expect(result).toEqual({
      status: "ineligible",
      reason: "cadence_mismatch",
      userId: "user_1",
      plan: "FREE",
      requestedCadence: "daily",
    });
  });

  it("handles no selected schools and no updates gracefully", () => {
    const result = generateSummaryForWindow({
      ...baseArgs,
      selectedSchoolIds: [],
      updates: [],
    });

    expect(result.status).toBe("eligible");
    if (result.status !== "eligible") return;
    expect(result.selectedSchoolCount).toBe(0);
    expect(result.updatedSchoolCount).toBe(0);
    expect(result.missedSchoolsCount).toBe(0);
    expect(result.totalRelevantUpdates).toBe(0);
    expect(result.summaryPayload.missedSchoolsMessage).toBeNull();
  });
});

import { describe, it, expect } from 'vitest'
import { aggregateSelectedSchoolUpdates, type SummaryUpdateRecord } from '../shared/summaryAggregation'

const fixtureUpdates: SummaryUpdateRecord[] = [
  { schoolId: 's1', updateId: 'a-1', at: 100 },
  { schoolId: 's1', updateId: 'a-1', at: 100 }, // duplicate
  { schoolId: 's1', updateId: 'a-2', at: 200 },
  { schoolId: 's2', updateId: 'b-1', at: 150 },
  { schoolId: 's3', updateId: 'c-1', at: 180 }, // unselected in tests
]

describe('summary aggregation', () => {
  it('aggregates only selected schools', () => {
    const result = aggregateSelectedSchoolUpdates({
      selectedSchoolIds: ['s1', 's2'],
      updates: fixtureUpdates,
      windowStart: 0,
      windowEnd: 1_000,
    })

    expect(result.selectedSchoolCount).toBe(2)
    expect(result.updatedSchoolCount).toBe(2)
    expect(result.missedSchoolsCount).toBe(0)
    expect(result.missedSchoolsMessage).toBeNull()
    expect(result.totalRelevantUpdates).toBe(3)
    expect(result.updateCountsBySchool).toEqual({
      s1: 2,
      s2: 1,
    })
  })

  it('respects inclusive window boundaries', () => {
    const result = aggregateSelectedSchoolUpdates({
      selectedSchoolIds: ['s1', 's2'],
      updates: fixtureUpdates,
      windowStart: 100,
      windowEnd: 150,
    })

    expect(result.totalRelevantUpdates).toBe(2)
    expect(result.missedSchoolsCount).toBe(0)
    expect(result.missedSchoolsMessage).toBeNull()
    expect(result.updateCountsBySchool).toEqual({
      s1: 1,
      s2: 1,
    })
  })

  it('returns deterministic counts on repeated runs with same fixture data', () => {
    const first = aggregateSelectedSchoolUpdates({
      selectedSchoolIds: ['s1', 's2'],
      updates: fixtureUpdates,
      windowStart: 0,
      windowEnd: 1_000,
    })
    const second = aggregateSelectedSchoolUpdates({
      selectedSchoolIds: ['s1', 's2'],
      updates: fixtureUpdates,
      windowStart: 0,
      windowEnd: 1_000,
    })

    expect(second).toEqual(first)
  })

  it('computes missedSchoolsCount for mixed update/no-update scenarios', () => {
    const result = aggregateSelectedSchoolUpdates({
      selectedSchoolIds: ['s1', 's2', 's4'],
      updates: fixtureUpdates,
      windowStart: 0,
      windowEnd: 1_000,
    })

    expect(result.selectedSchoolCount).toBe(3)
    expect(result.updatedSchoolCount).toBe(2)
    expect(result.missedSchoolsCount).toBe(1)
    expect(result.missedSchoolsMessage).toBe('1 selected school had no updates in this window.')
  })

  it('keeps missed-school messaging redacted (count-only, no school names)', () => {
    const result = aggregateSelectedSchoolUpdates({
      selectedSchoolIds: ['Alpha Primary School', 'Beta Primary School'],
      updates: [
        { schoolId: 'Alpha Primary School', updateId: 'alpha-1', at: 101 },
      ],
      windowStart: 0,
      windowEnd: 1_000,
    })

    expect(result.missedSchoolsCount).toBe(1)
    expect(result.missedSchoolsMessage).toBe('1 selected school had no updates in this window.')
    expect(result.missedSchoolsMessage).not.toContain('Alpha Primary School')
    expect(result.missedSchoolsMessage).not.toContain('Beta Primary School')
  })
})

import {
  aggregateSelectedSchoolUpdates,
  type AggregateSelectedSchoolUpdatesResult,
  type SummaryUpdateRecord,
} from "./summaryAggregation";
import {
  enforceCadence,
  type Plan,
  type SummaryCadence,
} from "./cadencePolicy";

export type SummaryPayload = AggregateSelectedSchoolUpdatesResult;

export type EligibleSummaryGenerationResult = {
  status: "eligible";
  userId: string;
  plan: Plan;
  cadence: SummaryCadence;
  windowStart: number;
  windowEnd: number;
  generatedAt: number;
  selectedSchoolCount: number;
  updatedSchoolCount: number;
  missedSchoolsCount: number;
  totalRelevantUpdates: number;
  summaryPayload: SummaryPayload;
};

export type IneligibleSummaryGenerationResult = {
  status: "ineligible";
  reason: "cadence_mismatch" | "invalid_plan";
  userId: string;
  plan?: string;
  requestedCadence: SummaryCadence;
};

export type ErrorSummaryGenerationResult = {
  status: "error";
  reason: string;
  userId: string;
};

export type SummaryGenerationResult =
  | EligibleSummaryGenerationResult
  | IneligibleSummaryGenerationResult
  | ErrorSummaryGenerationResult;

export type GenerateSummaryForWindowArgs = {
  userId: string;
  planInput: string;
  requestedCadence: SummaryCadence;
  windowStart: number;
  windowEnd: number;
  selectedSchoolIds: string[];
  updates: SummaryUpdateRecord[];
  generatedAt?: number;
};

export function generateSummaryForWindow(
  args: GenerateSummaryForWindowArgs
): SummaryGenerationResult {
  const cadence = enforceCadence(args.planInput, args.requestedCadence);
  if (cadence.status === "ineligible") {
    return {
      status: "ineligible",
      reason: cadence.reason,
      userId: args.userId,
      plan: cadence.plan,
      requestedCadence: cadence.requestedCadence,
    };
  }

  try {
    const summaryPayload = aggregateSelectedSchoolUpdates({
      selectedSchoolIds: args.selectedSchoolIds,
      updates: args.updates,
      windowStart: args.windowStart,
      windowEnd: args.windowEnd,
    });

    const generatedAt = args.generatedAt ?? Date.now();
    return {
      status: "eligible",
      userId: args.userId,
      plan: cadence.plan,
      cadence: cadence.requestedCadence,
      windowStart: args.windowStart,
      windowEnd: args.windowEnd,
      generatedAt,
      selectedSchoolCount: summaryPayload.selectedSchoolCount,
      updatedSchoolCount: summaryPayload.updatedSchoolCount,
      missedSchoolsCount: summaryPayload.missedSchoolsCount,
      totalRelevantUpdates: summaryPayload.totalRelevantUpdates,
      summaryPayload,
    };
  } catch (error) {
    const reason =
      error instanceof Error ? error.message : "summary_generation_failed";
    return {
      status: "error",
      reason,
      userId: args.userId,
    };
  }
}

export type SummaryUpdateRecord = {
  schoolId: string;
  updateId: string;
  at: number;
};

export type AggregateSelectedSchoolUpdatesArgs = {
  selectedSchoolIds: string[];
  updates: SummaryUpdateRecord[];
  windowStart: number;
  windowEnd: number;
};

export type AggregateSelectedSchoolUpdatesResult = {
  selectedSchoolCount: number;
  updatedSchoolCount: number;
  missedSchoolsCount: number;
  missedSchoolsMessage: string | null;
  totalRelevantUpdates: number;
  updateCountsBySchool: Record<string, number>;
};

/**
 * Aggregates updates for the caller's selected schools within an explicit time window.
 * Window boundaries are inclusive, and duplicates are collapsed by schoolId+updateId.
 */
export function aggregateSelectedSchoolUpdates(
  args: AggregateSelectedSchoolUpdatesArgs
): AggregateSelectedSchoolUpdatesResult {
  const { selectedSchoolIds, updates, windowStart, windowEnd } = args;

  if (windowStart > windowEnd) {
    throw new Error('Invalid summary window: windowStart must be <= windowEnd');
  }

  const normalizedSelectedSchoolIds = [...new Set(selectedSchoolIds)].sort();
  const selectedSet = new Set(normalizedSelectedSchoolIds);
  const deduped = new Map<string, SummaryUpdateRecord>();

  for (const update of updates) {
    if (!selectedSet.has(update.schoolId)) continue;
    if (update.at < windowStart || update.at > windowEnd) continue;

    const dedupeKey = `${update.schoolId}:${update.updateId}`;
    if (!deduped.has(dedupeKey)) {
      deduped.set(dedupeKey, update);
    }
  }

  const relevantUpdates = [...deduped.values()].sort((a, b) => {
    if (a.at !== b.at) return b.at - a.at;
    if (a.schoolId !== b.schoolId) return a.schoolId.localeCompare(b.schoolId);
    return a.updateId.localeCompare(b.updateId);
  });

  const updateCountsBySchool: Record<string, number> = {};
  for (const schoolId of normalizedSelectedSchoolIds) {
    updateCountsBySchool[schoolId] = 0;
  }
  for (const update of relevantUpdates) {
    updateCountsBySchool[update.schoolId] += 1;
  }

  const updatedSchoolCount = Object.values(updateCountsBySchool).filter((c) => c > 0).length;
  const missedSchoolsCount = normalizedSelectedSchoolIds.length - updatedSchoolCount;

  return {
    selectedSchoolCount: normalizedSelectedSchoolIds.length,
    updatedSchoolCount,
    missedSchoolsCount,
    missedSchoolsMessage: formatMissedSchoolsMessage(missedSchoolsCount),
    totalRelevantUpdates: relevantUpdates.length,
    updateCountsBySchool,
  };
}

export function formatMissedSchoolsMessage(missedSchoolsCount: number): string | null {
  if (missedSchoolsCount <= 0) return null;
  if (missedSchoolsCount === 1) return '1 selected school had no updates in this window.';
  return `${missedSchoolsCount} selected schools had no updates in this window.`;
}
